-- Question 57
-- Compare the total revenue generated by loyalty members
-- and non-loyalty members.

SELECT c.loyalty_member, ROUND(SUM(o.quantity * p.price)::numeric,2) AS total_revenue
FROM public.orders o
LEFT JOIN public.customers c
ON o.customer_id = c.customer_id
LEFT JOIN public.products p
ON o.product_id = p.product_id
GROUP BY c.loyalty_member